/**
 * Emulation of the Unicode general-category tests that CPython's
 * `str.isprintable()` relies on.
 *
 * CPython defines a character as non-printable when its general category is one
 * of Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs -- with the single exception of U+0020
 * (SPACE), which is always considered printable.
 *
 * Node exposes the same category data through RegExp Unicode property escapes,
 * so no table needs to be shipped.
 */

const NONPRINTABLE_CATEGORY = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;

/** SPACE is the one separator CPython still treats as printable. */
const SPACE = 0x20;

/**
 * @param {number} codePoint
 * @returns {boolean} true when CPython would consider the code point printable.
 */
export function isPrintableCodePoint(codePoint) {
  if (codePoint === SPACE) return true;
  return !NONPRINTABLE_CATEGORY.test(String.fromCodePoint(codePoint));
}

/**
 * Mirrors `str.isprintable()`. Note that CPython returns true for the empty
 * string.
 *
 * @param {string} text
 * @returns {boolean}
 */
export function isPrintable(text) {
  for (const character of text) {
    if (!isPrintableCodePoint(character.codePointAt(0))) return false;
  }
  return true;
}

/**
 * Iterates a string by Unicode code point, yielding lone surrogates as-is so
 * that `repr()` can escape them the way CPython does.
 *
 * @param {string} text
 * @returns {number[]} code points
 */
export function codePoints(text) {
  const points = [];
  for (let index = 0; index < text.length; index += 1) {
    const unit = text.charCodeAt(index);
    // High surrogate followed by a low surrogate forms one code point.
    if (unit >= 0xd800 && unit <= 0xdbff && index + 1 < text.length) {
      const next = text.charCodeAt(index + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        points.push((unit - 0xd800) * 0x400 + (next - 0xdc00) + 0x10000);
        index += 1;
        continue;
      }
    }
    points.push(unit);
  }
  return points;
}

