/**
 * Subset of CPython's `textwrap` module, covering the configuration argparse
 * uses: `textwrap.wrap(text, width)` with all defaults
 * (replace_whitespace=True, drop_whitespace=True, break_long_words=True,
 * break_on_hyphens=True).
 */

/**
 * CPython's `TextWrapper.wordsep_re`, transcribed. It splits text into chunks
 * of whitespace, hyphenated fragments and plain words so that line breaks may
 * land after a hyphen.
 */
const WORDSEP_RE = new RegExp(
  [
    '(\\s+|', // whitespace run
    '[^\\s\\w]*\\w+[^0-9\\W]-(?=[^0-9\\W]{2,})|', // hyphenated word
    '(?<=[\\w!"\'&.,?])-{2,}(?=\\w))', // em-dash
  ].join(''),
);

/** Whitespace is normalised to spaces before wrapping. */
function replaceWhitespace(text) {
  return text.replace(/[\t\n\v\f\r]/g, ' ');
}

/**
 * `TextWrapper._split`: break text into indivisible chunks.
 *
 * @param {string} text
 * @returns {string[]}
 */
function splitChunks(text) {
  return text.split(WORDSEP_RE).filter((chunk) => chunk !== '' && chunk !== undefined);
}

/**
 * `TextWrapper._handle_long_word`, simplified for the empty-indent case:
 * hard-break a chunk that cannot fit on a line by itself.
 */
function handleLongWord(chunks, currentLine, currentLength, width) {
  const spaceLeft = width < 1 ? 1 : width - currentLength;
  const chunk = chunks[chunks.length - 1];
  if (chunk.length > spaceLeft) {
    chunks[chunks.length - 1] = chunk.slice(spaceLeft);
    currentLine.push(chunk.slice(0, spaceLeft));
  } else {
    currentLine.push(chunks.pop());
  }
}

/**
 * Mirrors `textwrap.wrap(text, width)`.
 *
 * @param {string} text
 * @param {number} width
 * @returns {string[]} wrapped lines, never containing a trailing newline
 */
export function wrap(text, width) {
  const effectiveWidth = width > 0 ? width : 1;
  // `_munge_whitespace` then `_split`; chunks are consumed from the end.
  const chunks = splitChunks(replaceWhitespace(text)).reverse();
  const lines = [];

  while (chunks.length > 0) {
    const currentLine = [];
    let currentLength = 0;

    // drop_whitespace: leading whitespace on a continuation line is discarded.
    if (lines.length > 0 && /^\s+$/.test(chunks[chunks.length - 1])) {
      chunks.pop();
    }

    while (chunks.length > 0) {
      const chunkLength = chunks[chunks.length - 1].length;
      if (currentLength + chunkLength > effectiveWidth) break;
      currentLine.push(chunks.pop());
      currentLength += chunkLength;
    }

    // The chunk still pending is longer than a whole line: hard-break it.
    if (chunks.length > 0 && chunks[chunks.length - 1].length > effectiveWidth) {
      handleLongWord(chunks, currentLine, currentLength, effectiveWidth);
      currentLength = currentLine.reduce((sum, part) => sum + part.length, 0);
    }

    // drop_whitespace: trailing whitespace on any line is discarded.
    while (currentLine.length > 0 && /^\s+$/.test(currentLine[currentLine.length - 1])) {
      currentLength -= currentLine[currentLine.length - 1].length;
      currentLine.pop();
    }

    if (currentLine.length > 0) lines.push(currentLine.join(''));
  }

  return lines;
}

