/**
 * Minimal Python exception hierarchy: just enough for the exceptions this
 * program can raise, plus the traceback metadata needed to reproduce CPython's
 * report.
 */

import { pyRepr } from './repr.mjs';

/**
 * Base class carrying the Python-visible type name and the frames that make up
 * the traceback.
 */
export class PyException extends Error {
  /**
   * @param {string} typeName Python class name, e.g. "KeyError"
   * @param {string} detail   text printed after the colon
   */
  constructor(typeName, detail) {
    super(`${typeName}: ${detail}`);
    this.typeName = typeName;
    this.detail = detail;
    /** @type {Array<{file: string, line: number, name: string, source?: string, anchor?: string}>} */
    this.frames = [];
  }

  /** The final `KeyError: 'c'` style line of a traceback. */
  formatExceptionOnly() {
    return this.detail === '' ? this.typeName : `${this.typeName}: ${this.detail}`;
  }
}

/**
 * `KeyError`'s detail is `repr()` of the missing key, not `str()` -- which is
 * why `KeyError: 'c'` keeps its quotes.
 */
export class PyKeyError extends PyException {
  /** @param {*} key the missing key object */
  constructor(key) {
    super('KeyError', pyRepr(key));
    this.key = key;
  }
}

/** Raised by argparse for an invalid argument; carries the offending action. */
export class ArgumentError extends PyException {
  /**
   * @param {string|null} argumentName rendered name, e.g. "--key"
   * @param {string} message
   */
  constructor(argumentName, message) {
    const detail = argumentName === null ? message : `argument ${argumentName}: ${message}`;
    super('ArgumentError', detail);
    this.argumentName = argumentName;
    this.argMessage = message;
  }

  /** `str(ArgumentError)` -- what argparse feeds to `parser.error()`. */
  toStringPython() {
