/**
 * Hashability emulation.
 *
 * Python dict lookups are driven by `hash()` and `__eq__`, so `'1'` and `1` are
 * distinct keys while `1`, `1.0` and `True` all collide. Encoding each key to a
 * type-tagged token reproduces those equivalence classes using nothing but
 * ordinary string property access.
 */

import { NONE } from '../python/repr.mjs';

/** Raised for keys Python would reject as unhashable (list, dict, set). */
export class TypeErrorUnhashable extends Error {
  /** @param {string} typeName */
  constructor(typeName) {
    super(`unhashable type: '${typeName}'`);
    this.typeName = typeName;
  }
}

/**
 * Produces a token that is equal for exactly those values Python considers
 * equal-and-equally-hashed.
 *
 * The `n:` (numeric) bucket deliberately covers int, float and bool, because
 * Python's numeric tower makes `1 == 1.0 == True`.
 *
 * @param {*} key
 * @returns {string}
 */
export function hashToken(key) {
  if (key === NONE || key === null || key === undefined) return 'N';
  if (typeof key === 'string') return `s:${key}`;
  if (typeof key === 'boolean') return `n:${key ? 1 : 0}`;
  if (typeof key === 'bigint') return `n:${key.toString()}`;
  if (typeof key === 'number') {
    if (Number.isNaN(key)) return 'n:nan';
    // Normalise -0 to 0 and integral floats to their integer spelling so the
    // 1 / 1.0 collision is preserved.
    if (Number.isInteger(key)) return `n:${key === 0 ? 0 : key}`;
    return `n:${key}`;
  }
  if (Array.isArray(key)) throw new TypeErrorUnhashable('list');
  if (typeof key === 'object' && typeof key.hashToken === 'function') return key.hashToken();
  if (typeof key === 'object') throw new TypeErrorUnhashable('dict');
  return `o:${String(key)}`;
}

