/**
 * An insertion-ordered association store with Python `dict` semantics.
 *
 * Deliberately built from a null-prototype object used purely as a token ->
 * slot index, plus a slot array that preserves insertion order. Keys and values
 * are kept in their original JS form so that types survive round-tripping.
 */

import { hashToken } from './hashkey.mjs';

/** Sentinel marking a slot vacated by a delete. */
const VACANT = Symbol('vacant');

export class OrderedStore {
  constructor() {
    /** token -> index into `#slots` */
    this.index = Object.create(null);
    /** @type {Array<{key: *, value: *}|typeof VACANT>} */
    this.slots = [];
    /** live entry count, excluding vacated slots */
    this.count = 0;
  }

  /** @returns {number} number of live entries */
  get size() {
    return this.count;
  }

  /**
   * @param {*} key
   * @returns {boolean}
   */
  has(key) {
    return this.index[hashToken(key)] !== undefined;
  }

  /**
   * @param {*} key
   * @returns {*} stored value, or undefined when absent
   */
  get(key) {
    const slot = this.index[hashToken(key)];
    return slot === undefined ? undefined : this.slots[slot].value;
  }

  /**
   * Inserts or overwrites. An overwrite keeps the original insertion position,
   * exactly as Python's dict does.
   *
   * @param {*} key
   * @param {*} value
   */
  set(key, value) {
    const token = hashToken(key);
    const slot = this.index[token];
    if (slot === undefined) {
      this.index[token] = this.slots.length;
      this.slots.push({ key, value });
      this.count += 1;
    } else {
      this.slots[slot].value = value;
    }
  }

  /**
   * @param {*} key
   * @returns {boolean} true when an entry was removed
   */
  delete(key) {
    const token = hashToken(key);
    const slot = this.index[token];
    if (slot === undefined) return false;
    this.slots[slot] = VACANT;
    delete this.index[token];
    this.count -= 1;
    return true;
  }

  /** Drops every entry. */
  clear() {
    this.index = Object.create(null);
    this.slots = [];
    this.count = 0;
  }

  /**
   * @returns {Array<[*, *]>} live entries in insertion order
   */
  entries() {
    const result = [];
    for (const slot of this.slots) {
      if (slot !== VACANT) result.push([slot.key, slot.value]);
    }
    return result;
  }

  /** @returns {*[]} live keys in insertion order */
  keys() {
    return this.entries().map(([key]) => key);
  }

  /** @returns {*[]} live values in insertion order */
  values() {
    return this.entries().map(([, value]) => value);
  }
}

