/**
 * The bidict exception hierarchy, as observable from its public behaviour.
 *
 * A bidirectional mapping cannot silently accept a duplicate value the way a
 * plain dict can -- doing so would make the inverse mapping lossy -- so the
 * library raises instead.
 */

import { PyException } from '../python/exceptions.mjs';

/** Base class for every bidict-specific error. */
export class BidictException extends PyException {
  constructor(typeName, detail) {
    super(typeName, detail);
  }
}

/** Base class for the duplication errors. */
export class DuplicationError extends BidictException {
  constructor(typeName, detail) {
    super(typeName, detail);
  }
}

/** A key already present would be overwritten under a RAISE policy. */
export class KeyDuplicationError extends DuplicationError {
  constructor(detail) {
    super('KeyDuplicationError', detail);
  }
}

/** A value already bound to a different key -- the default failure mode. */
export class ValueDuplicationError extends DuplicationError {
  constructor(detail) {
    super('ValueDuplicationError', detail);
  }
}

/** Both sides collide, and each collides with a *different* existing item. */
export class KeyAndValueDuplicationError extends DuplicationError {
  constructor(detail) {
    super('KeyAndValueDuplicationError', detail);
  }
}

