/**
 * Duplication policies -- bidict's `OnDup` / `OnDupAction` values.
 *
 * The default used by the constructor and by `update()` keeps the newest item
 * when a *key* repeats, but refuses a repeated *value*.
 */

/** @enum {string} */
export const OnDupAction = Object.freeze({
  RAISE: 'RAISE',
  DROP_OLD: 'DROP_OLD',
  DROP_NEW: 'DROP_NEW',
});

export const { RAISE, DROP_OLD, DROP_NEW } = OnDupAction;

/**
 * @param {string} key action when the key already exists
 * @param {string} val action when the value already exists
 * @returns {{key: string, val: string}}
 */
export function OnDup(key = DROP_OLD, val = RAISE) {
  return Object.freeze({ key, val });
}

/** `bidict.ON_DUP_DEFAULT` -- used by `__init__`, `update` and `__setitem__`. */
export const ON_DUP_DEFAULT = OnDup(DROP_OLD, RAISE);

/** `bidict.ON_DUP_RAISE` -- used by `put` and `putall`. */
