/**
 * A bidirectional mapping: every key maps to exactly one value and every value
 * back to exactly one key.
 *
 * Reimplemented from observed behaviour. Two `OrderedStore`s are kept in step
 * -- forward and inverse -- and each mutation is validated against both before
 * either is touched, so a rejected write leaves the pair consistent.
 */

import { OrderedStore } from './ordered_store.mjs';
import { pyRepr } from '../python/repr.mjs';
import { PyKeyError } from '../python/exceptions.mjs';
import {
  KeyAndValueDuplicationError,
  KeyDuplicationError,
  ValueDuplicationError,
} from './errors.mjs';
import { DROP_NEW, DROP_OLD, ON_DUP_DEFAULT, ON_DUP_DROP_OLD, ON_DUP_RAISE, RAISE } from './on_dup.mjs';

/**
 * Source coordinates of bidict's own `__getitem__`, reported verbatim in a
 * traceback when a lookup misses.
 */
export const GETITEM_FRAME = Object.freeze({
  file: 'bidict/_base.py',
  line: 524,
  name: '__getitem__',
});

/** Sentinel distinguishing "argument omitted" from an explicit `undefined`. */
const MISSING = Symbol('missing');

/**
 * Normalises the many accepted constructor inputs into a list of pairs.
 *
 * @param {*} source
 * @returns {Array<[*, *]>}
 */
function toPairs(source) {
  if (source === undefined || source === null) return [];
  if (source instanceof BidirectionalDict) return source.items();
  if (Array.isArray(source)) return source.map(([key, value]) => [key, value]);
  if (typeof source === 'object') return Object.keys(source).map((key) => [key, source[key]]);
  throw new TypeError('bidict expected a mapping or an iterable of pairs');
}

export class BidirectionalDict {
  /**
   * @param {Array<[*, *]>|Object|BidirectionalDict} [source]
   */
  constructor(source) {
    /** forward: key -> value */
    this.forward = new OrderedStore();
    /** inverse: value -> key */
    this.backward = new OrderedStore();
    /** lazily created view sharing this instance's stores */
    this.inverseView = null;

    for (const [key, value] of toPairs(source)) {
      this.write(key, value, ON_DUP_DEFAULT);
    }
  }

  /** @returns {number} `len(bidict)` */
  get size() {
    return this.forward.size;
  }

  /** @returns {number} `len(bidict)` */
  len() {
    return this.forward.size;
  }

  /**
   * The inverse mapping. Mutating either side is visible through the other,
   * because both objects share the same two stores.
   *
   * @returns {BidirectionalDict}
   */
  get inverse() {
    if (this.inverseView === null) {
      const view = Object.create(BidirectionalDict.prototype);
      view.forward = this.backward;
      view.backward = this.forward;
      view.inverseView = this;
      this.inverseView = view;
    }
    return this.inverseView;
  }

  /** Alias kept for parity with bidict's `.inv` shorthand. */
  get inv() {
    return this.inverse;
  }

  /**
   * `bidict[key]`. Raises KeyError -- carrying the traceback frame CPython
   * would have shown -- when the key is absent.
   *
   * @param {*} key
   * @returns {*}
   */
  getItem(key) {
    if (!this.forward.has(key)) {
      const error = new PyKeyError(key);
      error.frames.push({ ...GETITEM_FRAME });
      throw error;
    }
    return this.forward.get(key);
  }

  /**
   * `bidict.get(key, default)` -- never raises.
   *
   * @param {*} key
   * @param {*} [fallback]
   * @returns {*}
   */
  get(key, fallback = undefined) {
    return this.forward.has(key) ? this.forward.get(key) : fallback;
  }

  /**
   * `key in bidict`
   *
   * @param {*} key
   * @returns {boolean}
   */
  contains(key) {
    return this.forward.has(key);
  }

  /**
   * Core mutation, shared by `__setitem__`, `put` and `forceput`.
   *
   * Classifies the write against both stores first, applies the requested
   * policy, and only then commits -- so a RAISE leaves the mapping untouched.
   *
   * @param {*} key
   * @param {*} value
   * @param {{key: string, val: string}} onDup
   */
  write(key, value, onDup) {
    const keyExists = this.forward.has(key);
    const valueExists = this.backward.has(value);
    // A pair that is already present in both directions is a no-op, not a
    // duplication error.
    const sameItem = keyExists && valueExists && this.backward.get(value) === undefined
      ? false
      : keyExists && valueExists
        && this.forward.get(key) === value
        && this.backward.get(value) === key;

    if (sameItem) return;

    if (keyExists && valueExists) {
      if (onDup.key === RAISE || onDup.val === RAISE) {
        throw new KeyAndValueDuplicationError(pyRepr([key, value]).replace(/^\[|\]$/g, '(') );
      }
      if (onDup.key === DROP_NEW || onDup.val === DROP_NEW) return;
