export const GETITEM_FRAME = Object.freeze({
  file: 'bidict/_base.py',
  line: 524,
  name: '__getitem__',
});

/** Sentinel distinguishing "argument omitted" from an explicit `undefined`. */
const MISSING = Symbol('missing');

/**
 * Normalises the many accepted constructor inputs into a list of pairs.
 *
 * @param {*} source
 * @returns {Array<[*, *]>}
 */
function toPairs(source) {
  if (source === undefined || source === null) return [];
  if (source instanceof BidirectionalDict) return source.items();
  if (Array.isArray(source)) return source.map(([key, value]) => [key, value]);
  if (typeof source === 'object') return Object.keys(source).map((key) => [key, source[key]]);
  throw new TypeError('bidict expected a mapping or an iterable of pairs');
}

export class BidirectionalDict {
  /**
   * @param {Array<[*, *]>|Object|BidirectionalDict} [source]
   */
  constructor(source) {
    /** forward: key -> value */
    this.forward = new OrderedStore();
    /** inverse: value -> key */
    this.backward = new OrderedStore();
    /** lazily created view sharing this instance's stores */
    this.inverseView = null;

    for (const [key, value] of toPairs(source)) {
      this.write(key, value, ON_DUP_DEFAULT);
    }
  }

  /** @returns {number} `len(bidict)` */
  get size() {
    return this.forward.size;
  }

  /** @returns {number} `len(bidict)` */
  len() {
    return this.forward.size;
  }

  /**
   * The inverse mapping. Mutating either side is visible through the other,
   * because both objects share the same two stores.
   *
   * @returns {BidirectionalDict}
   */
  get inverse() {
    if (this.inverseView === null) {
      const view = Object.create(BidirectionalDict.prototype);
      view.forward = this.backward;
      view.backward = this.forward;
      view.inverseView = this;
      this.inverseView = view;
    }
    return this.inverseView;
  }

  /** Alias kept for parity with bidict's `.inv` shorthand. */
  get inv() {
    return this.inverse;
  }

  /**
   * `bidict[key]`. Raises KeyError -- carrying the traceback frame CPython
   * would have shown -- when the key is absent.
   *
   * @param {*} key
   * @returns {*}
   */
  getItem(key) {
    if (!this.forward.has(key)) {
      const error = new PyKeyError(key);
      error.frames.push({ ...GETITEM_FRAME });
      throw error;
    }
    return this.forward.get(key);
  }

  /**
   * `bidict.get(key, default)` -- never raises.
   *
   * @param {*} key
   * @param {*} [fallback]
   * @returns {*}
   */
  get(key, fallback = undefined) {
    return this.forward.has(key) ? this.forward.get(key) : fallback;
  }

  /**
   * `key in bidict`
   *
   * @param {*} key
   * @returns {boolean}
   */
  contains(key) {
    return this.forward.has(key);
  }

  /**
   * Core mutation, shared by `__setitem__`, `put` and `forceput`.
   *
   * Classifies the write against both stores first, applies the requested
   * policy, and only then commits -- so a RAISE leaves the mapping untouched.
   *
   * @param {*} key
   * @param {*} value
   * @param {{key: string, val: string}} onDup
   */
  write(key, value, onDup) {
    const keyExists = this.forward.has(key);
    const valueExists = this.backward.has(value);

    // An item already present in both directions is a no-op rather than a
    // duplication. Compare by hash token so Python's equality rules apply.
    if (keyExists && valueExists
      && hashToken(this.forward.get(key)) === hashToken(value)
      && hashToken(this.backward.get(value)) === hashToken(key)) {
      return;
    }

    if (keyExists && valueExists) {
      if (onDup.key === RAISE || onDup.val === RAISE) {
        throw new KeyAndValueDuplicationError(`(${pyRepr(key)}, ${pyRepr(value)})`);
      }
      if (onDup.key === DROP_NEW || onDup.val === DROP_NEW) return;
    } else if (keyExists) {
      if (onDup.key === RAISE) throw new KeyDuplicationError(pyRepr(key));
      if (onDup.key === DROP_NEW) return;
    } else if (valueExists) {
      if (onDup.val === RAISE) throw new ValueDuplicationError(pyRepr(value));
      if (onDup.val === DROP_NEW) return;
    }

    // Unlink whatever currently occupies either side, then link the new pair.
    if (keyExists) this.backward.delete(this.forward.get(key));
    if (valueExists) this.forward.delete(this.backward.get(value));
    this.forward.set(key, value);
    this.backward.set(value, key);
  }

  /**
   * `bidict[key] = value` -- overwrites a repeated key, rejects a repeated
   * value.
   *
   * @param {*} key
   * @param {*} value
   */
  setItem(key, value) {
    this.write(key, value, ON_DUP_DEFAULT);
  }

  /**
   * `bidict.put(key, value)` -- rejects a duplicate on either side.
   *
   * @param {*} key
   * @param {*} value
   */
  put(key, value) {
    this.write(key, value, ON_DUP_RAISE);
  }

  /**
   * `bidict.forceput(key, value)` -- always wins, evicting any conflict.
   *
   * @param {*} key
   * @param {*} value
   */
  forceput(key, value) {
    this.write(key, value, ON_DUP_DROP_OLD);
  }

  /**
   * `del bidict[key]`
   *
   * @param {*} key
   */
  delItem(key) {
    if (!this.forward.has(key)) {
      const error = new PyKeyError(key);
      error.frames.push({ ...GETITEM_FRAME });
      throw error;
    }
    const value = this.forward.get(key);
    this.forward.delete(key);
    this.backward.delete(value);
  }

  /**
   * `bidict.pop(key[, default])`
   *
   * @param {*} key
   * @param {*} [fallback]
   * @returns {*}
   */
  pop(key, fallback = MISSING) {
    if (!this.forward.has(key)) {
      if (fallback === MISSING) {
        const error = new PyKeyError(key);
        error.frames.push({ ...GETITEM_FRAME });
        throw error;
      }
      return fallback;
    }
    const value = this.forward.get(key);
    this.forward.delete(key);
    this.backward.delete(value);
    return value;
  }

  /** Removes every item from both directions. */
  clear() {
    this.forward.clear();
    this.backward.clear();
  }

  /** @returns {*[]} keys in insertion order */
  keys() {
    return this.forward.keys();
  }

  /** @returns {*[]} values in insertion order */
  values() {
    return this.forward.values();
  }

  /** @returns {Array<[*, *]>} items in insertion order */
  items() {
    return this.forward.entries();
  }

  /** Iterating a bidict yields its keys, as in Python. */
  *[Symbol.iterator]() {
    yield* this.forward.keys();
  }

  /**
   * `repr(bidict)` -- e.g. `bidict({'a': 1, 'b': 2})`.
   *
   * @returns {string}
   */
  __repr__() {
    const body = this.items()
      .map(([key, value]) => `${pyRepr(key)}: ${pyRepr(value)}`)
      .join(', ');
    return `bidict({${body}})`;
  }
}

/**
 * Factory mirroring the `bidict(...)` call form used in Python.
 *
 * @param {Array<[*, *]>|Object|BidirectionalDict} [source]
 * @returns {BidirectionalDict}
 */
export function bidict(source) {
  return new BidirectionalDict(source);
}

