/**
 * Argument actions.
 *
 * Only the two kinds this parser needs exist: `store` (consume one value) and
 * `help` (print help and exit). `nargs === 0` marks an action that takes no
 * value, which the usage formatter keys off.
 */

/** `argparse.SUPPRESS` */
export const SUPPRESS = '==SUPPRESS==';

export class Action {
  /**
   * @param {object} spec
   * @param {string[]} spec.optionStrings
   * @param {string} spec.dest
   * @param {number|string|null} [spec.nargs]
   * @param {boolean} [spec.required]
   * @param {string} [spec.help]
   * @param {string|null} [spec.metavar]
   * @param {((text: string) => *)|null} [spec.type]
   * @param {*} [spec.defaultValue]
   */
  constructor({
    optionStrings,
    dest,
    nargs = null,
    required = false,
    help = '',
    metavar = null,
    type = null,
    defaultValue = null,
  }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
    this.type = type;
    this.defaultValue = defaultValue;
  }

  /** `action.format_usage()` -- how a zero-argument option appears in usage. */
  formatUsage() {
    return this.optionStrings[0];
  }

  /**
   * Applies the action's effect to the namespace.
   *
   * @param {object} parser
   * @param {object} namespace
   * @param {*} values
   */
  // eslint-disable-next-line no-unused-vars
  call(parser, namespace, values) {
    throw new Error('.call() not implemented');
  }
}

/** `action='store'` -- assigns the parsed value to `dest`. */
export class StoreAction extends Action {
  call(parser, namespace, values) {
    namespace[this.dest] = values;
  }
}

/** `action='help'` -- prints help to stdout and exits 0. */
export class HelpAction extends Action {
  constructor(spec) {
    super({ ...spec, nargs: 0, defaultValue: SUPPRESS });
  }

  call(parser) {
    parser.printHelp();
    parser.exit(0);
  }
}

