export class HelpFormatter {
  /**
   * @param {object} options
   * @param {string} options.prog
   * @param {number} [options.indentIncrement]
   * @param {number} [options.maxHelpPosition]
   * @param {number} [options.width] usable width; defaults to terminal - 2
   */
  constructor({ prog, indentIncrement = 2, maxHelpPosition = 24, width = undefined }) {
    this.prog = prog;
    this.indentIncrement = indentIncrement;
    this.width = width ?? getTerminalSize().columns - 2;
    // CPython shrinks the help column cap on narrow terminals.
    this.maxHelpPosition = Math.min(
      maxHelpPosition,
      Math.max(this.width - 20, indentIncrement * 2),
    );
    this.currentIndent = 0;
    this.actionMaxLength = 0;
  }

  indent() {
    this.currentIndent += this.indentIncrement;
  }

  dedent() {
    this.currentIndent -= this.indentIncrement;
  }

  /**
   * Registers an action so the help column can be sized. Mirrors
   * `add_argument`, which measures the invocation *plus* the current indent.
   *
   * @param {import('./actions.mjs').Action} action
   */
  addAction(action) {
    if (action.help === SUPPRESS) return;
    const invocation = this.formatActionInvocation(action);
    const actionLength = invocation.length + this.currentIndent;
    this.actionMaxLength = Math.max(this.actionMaxLength, actionLength);
  }

  /**
   * The metavar an option shows for its value: an explicit `metavar`, else the
   * uppercased dest.
   *
   * @param {import('./actions.mjs').Action} action
   * @returns {string}
   */
  metavarFor(action) {
    if (action.metavar !== null && action.metavar !== undefined) return action.metavar;
    return action.dest.toUpperCase();
  }

  /**
   * `_format_action_invocation` -- the left-hand column of the options list.
   * Zero-argument options list their flags alone; value-taking options repeat
   * the metavar after each flag.
   *
   * @param {import('./actions.mjs').Action} action
   * @returns {string}
   */
  formatActionInvocation(action) {
    if (action.optionStrings.length === 0) return this.metavarFor(action);
    if (action.nargs === 0) return action.optionStrings.join(', ');
    const metavar = this.metavarFor(action);
    return action.optionStrings.map((option) => `${option} ${metavar}`).join(', ');
  }

  /**
   * `_format_actions_usage` -- the bracketed argument summary on the usage
   * line. Optional actions are wrapped in square brackets; required ones are
   * bare.
   *
   * @param {import('./actions.mjs').Action[]} actions
   * @returns {string}
   */
  formatActionsUsage(actions) {
    const parts = [];
    for (const action of actions) {
      if (action.help === SUPPRESS) continue;
      let part;
      if (action.optionStrings.length === 0) {
        part = this.metavarFor(action);
      } else if (action.nargs === 0) {
        part = action.formatUsage();
      } else {
        part = `${action.optionStrings[0]} ${this.metavarFor(action)}`;
      }
      if (!action.required) part = `[${part}]`;
      parts.push(part);
    }
    return parts.join(' ');
  }

  /**
   * Packs parts into lines no wider than `textWidth`, mirroring the nested
   * `get_lines` helper in `_format_usage`.
   *
   * @param {string[]} parts
   * @param {string} indent
   * @param {number} textWidth
   * @param {string|null} prefix present only for the first, prog-sharing line
   * @returns {string[]}
   */
  static getLines(parts, indent, textWidth, prefix) {
    const lines = [];
    let line = [];
    // Seeded one short so the first `+ 1 + len(part)` accounts for no leading
    // space -- CPython's own off-by-one, reproduced.
    let lineLength = (prefix !== null ? prefix.length : indent.length) - 1;

    for (const part of parts) {
      if (lineLength + 1 + part.length > textWidth && line.length > 0) {
        lines.push(indent + line.join(' '));
        line = [];
        lineLength = indent.length - 1;
      }
      line.push(part);
      lineLength += 1 + part.length;
    }
    if (line.length > 0) lines.push(indent + line.join(' '));
    if (prefix !== null && lines.length > 0) lines[0] = lines[0].slice(indent.length);
    return lines;
  }

  /**
   * `_format_usage` -- returns the usage block including its trailing blank
   * line.
   *
   * @param {import('./actions.mjs').Action[]} actions
   * @returns {string}
   */
  formatUsage(actions) {
    const optionals = actions.filter((action) => action.optionStrings.length > 0);
    const positionals = actions.filter((action) => action.optionStrings.length === 0);

    const optionalUsage = this.formatActionsUsage(optionals);
    const positionalUsage = this.formatActionsUsage(positionals);
    let usage = [optionalUsage, positionalUsage].filter((piece) => piece !== '').join(' ');
    usage = usage === '' ? this.prog : `${this.prog} ${usage}`;

    const textWidth = this.width - this.currentIndent;

    if (USAGE_PREFIX.length + usage.length > textWidth) {
      const optParts = optionalUsage.match(PART_RE) ?? [];
      const posParts = positionalUsage.match(PART_RE) ?? [];
      let lines;

      if (USAGE_PREFIX.length + this.prog.length <= 0.75 * textWidth) {
        // Keep the program name on the first line and hang the rest under it.
        const indent = spaces(USAGE_PREFIX.length + this.prog.length + 1);
        if (optParts.length > 0) {
          lines = HelpFormatter.getLines([this.prog, ...optParts], indent, textWidth, USAGE_PREFIX);
          lines.push(...HelpFormatter.getLines(posParts, indent, textWidth, null));
        } else if (posParts.length > 0) {
          lines = HelpFormatter.getLines([this.prog, ...posParts], indent, textWidth, USAGE_PREFIX);
        } else {
          lines = [this.prog];
        }
      } else {
        // Too narrow to share: the program name gets its own line.
        const indent = spaces(USAGE_PREFIX.length);
        lines = HelpFormatter.getLines([...optParts, ...posParts], indent, textWidth, null);
        if (lines.length > 1) {
          lines = [
            ...HelpFormatter.getLines(optParts, indent, textWidth, null),
            ...HelpFormatter.getLines(posParts, indent, textWidth, null),
          ];
        }
        lines = [this.prog, ...lines];
      }
      usage = lines.join('\n');
    }

    return `${USAGE_PREFIX}${usage}\n\n`;
  }

  /**
   * `_format_action` -- one entry of the options list, including its wrapped
   * help text.
   *
   * @param {import('./actions.mjs').Action} action
   * @returns {string}
   */
  formatAction(action) {
    const helpPosition = Math.min(this.actionMaxLength + 2, this.maxHelpPosition);
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - this.currentIndent - 2;
    const invocation = this.formatActionInvocation(action);

    let header;
    let indentFirst;
    if (!action.help) {
      // No help text: emit the invocation alone, with no padding, so no
      // trailing whitespace is produced.
      header = `${spaces(this.currentIndent)}${invocation}\n`;
      indentFirst = 0;
    } else if (invocation.length <= actionWidth) {
      header = `${spaces(this.currentIndent)}${invocation.padEnd(actionWidth)}  `;
      indentFirst = 0;
    } else {
      header = `${spaces(this.currentIndent)}${invocation}\n`;
      indentFirst = helpPosition;
    }

    const parts = [header];
    if (action.help && action.help.trim() !== '') {
      // `_split_lines`: collapse whitespace runs, then wrap.
      const collapsed = action.help.replace(/\s+/g, ' ').trim();
      const helpLines = wrap(collapsed, helpWidth);
      if (helpLines.length > 0) {
        parts.push(`${spaces(indentFirst)}${helpLines[0]}\n`);
        for (const line of helpLines.slice(1)) {
          parts.push(`${spaces(helpPosition)}${line}\n`);
        }
      }
    } else if (!header.endsWith('\n')) {
      parts.push('\n');
    }
    return parts.join('');
  }

  /**
   * Renders a titled group of actions. A group with nothing to show produces
   * the empty string, which is why `positional arguments:` never appears here.
   *
   * @param {string} title
   * @param {import('./actions.mjs').Action[]} actions
   * @returns {string}
   */
  formatSection(title, actions) {
    this.indent();
    const body = actions
      .filter((action) => action.help !== SUPPRESS)
      .map((action) => this.formatAction(action))
      .join('');
    this.dedent();
    if (body === '') return '';
    return `${title}:\n${body}\n`;
  }

  /**
   * Final assembly: collapse runs of blank lines and normalise to exactly one
   * trailing newline, as `format_help` does.
   *
   * @param {string} text
   * @returns {string}
   */
  static finalize(text) {
    if (text === '') return text;
    return `${text.replace(/\n\n\n+/g, '\n\n').replace(/^\n+|\n+$/g, '')}\n`;
  }
}

