/**
 * Reimplementation of `argparse.ArgumentParser`, covering the behaviours this
 * program can reach.
 *
 * Parsing follows CPython's two-phase design: every token is first classified
 * into a pattern string ('O' option, 'A' positional-ish, '-' for a bare `--`),
 * and actions then consume slices of that pattern. Reproducing this structure
 * -- rather than scanning tokens ad hoc -- is what makes the awkward cases come
 * out right, e.g. `--key -- --val 1` reporting "expected one argument" because
 * `--` classifies as '-' and a value-taking option's pattern only accepts 'A'.
 */

import { HelpFormatter } from './help_formatter.mjs';
import { HelpAction, StoreAction, SUPPRESS } from './actions.mjs';
import { ArgumentError, SystemExit } from '../python/exceptions.mjs';
import { stderrWrite, stdoutWrite } from '../python/sys_io.mjs';

/** `argparse`'s test for a token that merely looks like a negative number. */
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

/** Messages keyed by nargs, as in `_match_argument`. */
const NARGS_ERRORS = {
  null: 'expected one argument',
  '?': 'expected at most one argument',
  '+': 'expected at least one argument',
};

export class ArgumentParser {
  /**
   * @param {object} [options]
   * @param {string} [options.prog] program name used in usage/error text
   * @param {string} [options.prefixChars]
   * @param {boolean} [options.addHelp]
   * @param {boolean} [options.allowAbbrev]
   */
  constructor({ prog = undefined, prefixChars = '-', addHelp = true, allowAbbrev = true } = {}) {
    // CPython derives prog from `os.path.basename(sys.argv[0])`. The reference
    // build is a frozen executable, so its own name is what appears in usage
    // and error output -- including `--help`, which goes to stdout.
    this.prog = prog ?? 'test2_executable';
    this.prefixChars = prefixChars;
    this.allowAbbrev = allowAbbrev;

    /** @type {import('./actions.mjs').Action[]} in definition order */
    this.actions = [];
    /** option string -> action */
    this.optionStringActions = Object.create(null);

    if (addHelp) {
      this.addArgument(['-h', '--help'], {
        action: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  /**
   * Registers an argument. Mirrors `add_argument` for the option forms used
   * here.
   *
   * @param {string[]|string} optionStrings
   * @param {object} [spec]
   * @param {string} [spec.action] 'store' or 'help'
   * @param {boolean} [spec.required]
   * @param {string} [spec.help]
   * @param {string|null} [spec.metavar]
   * @param {((text: string) => *)|null} [spec.type]
   * @param {*} [spec.defaultValue]
   * @returns {import('./actions.mjs').Action}
   */
  addArgument(optionStrings, spec = {}) {
    const options = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
    // dest comes from the first long option, with the prefix stripped and
    // internal dashes turned into underscores.
    const longOption = options.find((option) => option.startsWith(this.prefixChars.repeat(2)));
    const source = longOption ?? options[0];
    const dest = source.replace(new RegExp(`^[${this.prefixChars}]+`), '').replace(/-/g, '_');

    const common = {
      optionStrings: options,
      dest,
      required: spec.required ?? false,
      help: spec.help ?? '',
      metavar: spec.metavar ?? null,
      type: spec.type ?? null,
      defaultValue: spec.defaultValue ?? null,
    };

    const action = spec.action === 'help' ? new HelpAction(common) : new StoreAction(common);
    this.actions.push(action);
    for (const option of options) this.optionStringActions[option] = action;
    return action;
  }

  /** True when some option itself looks like a negative number. */
  get hasNegativeNumberOptionals() {
    return Object.keys(this.optionStringActions).some((option) => NEGATIVE_NUMBER_RE.test(option));
  }

  /** @returns {HelpFormatter} */
  formatter() {
    return new HelpFormatter({ prog: this.prog });
  }

  /** @returns {string} the usage block, one trailing newline */
  formatUsage() {
    const formatter = this.formatter();
    return HelpFormatter.finalize(formatter.formatUsage(this.actions));
  }

  /** @returns {string} the complete help text */
  formatHelp() {
    const formatter = this.formatter();
    for (const action of this.actions) formatter.addAction(action);

    let text = formatter.formatUsage(this.actions);
    // Positionals come first, then the options group. An empty group renders
    // as nothing, so `positional arguments:` is absent here.
    const positionals = this.actions.filter((action) => action.optionStrings.length === 0);
    const optionals = this.actions.filter((action) => action.optionStrings.length > 0);
    text += formatter.formatSection('positional arguments', positionals);
    text += formatter.formatSection('options', optionals);
    return HelpFormatter.finalize(text);
  }

  /** Writes usage to stderr. */
  printUsage(target = stderrWrite) {
    target(this.formatUsage());
  }

  /** Writes full help to stdout. */
  printHelp() {
    stdoutWrite(this.formatHelp());
  }

  /**
   * `parser.exit()` -- unwinds via SystemExit so callers can flush first.
   *
   * @param {number} [status]
   * @param {string|null} [message]
   * @returns {never}
   */
  exit(status = 0, message = null) {
    if (message) stderrWrite(message);
    throw new SystemExit(status);
  }

  /**
   * `parser.error()` -- prints usage plus the message and exits 2.
   *
   * @param {string} message
   * @returns {never}
   */
  error(message) {
    this.printUsage(stderrWrite);
    this.exit(2, `${this.prog}: error: ${message}\n`);
  }

  /**
   * `_get_action_name` -- how an action is named in the required-args message.
   *
   * @param {import('./actions.mjs').Action} action
   * @returns {string}
   */
  static actionName(action) {
    if (action.optionStrings.length > 0) return action.optionStrings.join('/');
    if (action.metavar !== null && action.metavar !== SUPPRESS) return action.metavar;
    return action.dest;
  }

  /**
   * `_get_nargs_pattern` -- regex fragment describing what an action consumes.
   * Optionals drop the `-*` slack, which is why they refuse to reach across a
   * `--`.
   *
   * @param {import('./actions.mjs').Action} action
   * @returns {string}
   */
  static nargsPattern(action) {
    const { nargs } = action;
    let pattern;
    if (nargs === null || nargs === undefined) pattern = '(-*A-*)';
    else if (nargs === '?') pattern = '(-*A?-*)';
    else if (nargs === '*') pattern = '(-*[A-]*)';
    else if (nargs === '+') pattern = '(-*A[A-]*)';
    else if (nargs === 0) pattern = '(-*-*)';
    else pattern = `(-*${Array.from({ length: nargs }, () => 'A').join('-*')}-*)`;

    if (action.optionStrings.length > 0) {
      pattern = pattern.split('-*').join('').split('-').join('');
    }
    return pattern;
  }

  /**
   * `_match_argument` -- how many tokens this action takes from the pattern.
   *
   * @param {import('./actions.mjs').Action} action
   * @param {string} pattern
   * @returns {number}
   */
  matchArgument(action, pattern) {
    const regex = new RegExp(`^${ArgumentParser.nargsPattern(action)}`);
    const match = regex.exec(pattern);
    if (match === null) {
      const key = action.nargs === null || action.nargs === undefined ? 'null' : String(action.nargs);
      const message = NARGS_ERRORS[key] ?? `expected ${action.nargs} arguments`;
      throw new ArgumentError(ArgumentParser.actionName(action), message);
    }
    return match[1].length;
  }

  /**
   * `_match_arguments_partial` -- greedily fit as many positionals as possible.
   *
   * @param {import('./actions.mjs').Action[]} actions
   * @param {string} pattern
   * @returns {number[]} token counts, one per matched action
   */
  static matchArgumentsPartial(actions, pattern) {
    for (let count = actions.length; count > 0; count -= 1) {
      const slice = actions.slice(0, count);
      const regex = new RegExp(`^${slice.map(ArgumentParser.nargsPattern).join('')}`);
      const match = regex.exec(pattern);
      if (match !== null) return match.slice(1).map((group) => group.length);
    }
    return [];
  }

  /**
   * `_parse_optional` -- classify one token.
   *
   * @param {string} token
   * @returns {[import('./actions.mjs').Action|null, string, string|null, string|null]|null}
   *   null means "treat as positional"; an entry with a null action means
   *   "looks like an option but is unknown".
   */
  parseOptional(token) {
    if (token === '') return null;
    if (!this.prefixChars.includes(token[0])) return null;

    const exact = this.optionStringActions[token];
    if (exact !== undefined) return [exact, token, null, null];

    if (token.length === 1) return null;

    const equals = token.indexOf('=');
    if (equals !== -1) {
      const head = token.slice(0, equals);
      const tail = token.slice(equals + 1);
      const action = this.optionStringActions[head];
      if (action !== undefined) return [action, head, '=', tail];
    }

    const tuples = this.optionTuples(token);
    if (tuples.length > 1) {
      const matches = tuples.map((tuple) => tuple[1]).join(', ');
      this.error(`ambiguous option: ${token} could match ${matches}`);
    }
    if (tuples.length === 1) return tuples[0];

    // A bare negative number is a value, not an unknown flag -- unless some
    // option is itself spelled like one.
    if (NEGATIVE_NUMBER_RE.test(token) && !this.hasNegativeNumberOptionals) return null;
    if (token.includes(' ')) return null;

    return [null, token, null, null];
  }

  /**
   * `_get_option_tuples` -- abbreviation matching for long options.
   *
   * @param {string} token
   * @returns {Array<[import('./actions.mjs').Action, string, string|null, string|null]>}
   */
  optionTuples(token) {
    const result = [];
    const chars = this.prefixChars;
    const isLong = chars.includes(token[0]) && token.length > 1 && chars.includes(token[1]);

    if (isLong) {
      if (!this.allowAbbrev) return result;
      const equals = token.indexOf('=');
      const prefix = equals === -1 ? token : token.slice(0, equals);
      const explicit = equals === -1 ? null : token.slice(equals + 1);
      const sep = equals === -1 ? null : '=';
      for (const option of Object.keys(this.optionStringActions)) {
        if (option.startsWith(prefix)) {
          result.push([this.optionStringActions[option], option, sep, explicit]);
        }
      }
    } else if (chars.includes(token[0])) {
      // Short option, possibly with an attached value: -f or -fbar.
      const optionPrefix = token;
      const shortOption = token.slice(0, 2);
      const shortExplicit = token.slice(2);
      for (const option of Object.keys(this.optionStringActions)) {
        if (option === shortOption) {
          result.push([this.optionStringActions[option], option, '', shortExplicit]);
        } else if (option.startsWith(optionPrefix)) {
          result.push([this.optionStringActions[option], option, null, null]);
        }
      }
    }
    return result;
  }

  /**
   * `parse_args` -- like `parse_known_args`, but leftover tokens are an error.
   *
   * @param {string[]} argv
   * @returns {object} namespace
   */
  parseArgs(argv) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  /**
   * `parse_known_args` / `_parse_known_args`.
   *
   * @param {string[]} argv
   * @returns {[object, string[]]} namespace and unrecognized tokens
   */
  parseKnownArgs(argv) {
    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (action.defaultValue !== SUPPRESS) namespace[action.dest] = action.defaultValue;
    }

    const args = [...argv];
    /** @type {string[]} */
    const extras = [];
    /** index -> option tuple */
    const optionIndices = Object.create(null);
    let pattern = '';

    // Phase one: classify every token.
    for (let i = 0; i < args.length; i += 1) {
      if (args[i] === '--') {
        pattern += '-';
        // Everything after the first `--` is forced positional.
        for (let j = i + 1; j < args.length; j += 1) pattern += 'A';
        break;
      }
      const optionTuple = this.parseOptional(args[i]);
      if (optionTuple === null) {
        pattern += 'A';
      } else {
        optionIndices[i] = optionTuple;
        pattern += 'O';
      }
    }

    /** actions that were encountered at all -- drives the required check */
    const seen = [];
    const positionalActions = this.actions.filter((action) => action.optionStrings.length === 0);
    const pendingPositionals = [...positionalActions];

    const takeAction = (action, argStrings, optionString) => {
      if (!seen.includes(action)) seen.push(action);
      const values = this.getValues(action, argStrings);
      action.call(this, namespace, values, optionString);
    };

    /**
     * Consume one optional starting at `startIndex`; returns the next index.
     */
    const consumeOptional = (startIndex) => {
      const [action, optionString, sep, explicitArg] = optionIndices[startIndex];

      if (action === null) {
        extras.push(args[startIndex]);
        return startIndex + 1;
      }

      let stop;
      let values;
      if (explicitArg !== null && explicitArg !== undefined) {
        const argCount = this.matchArgument(action, 'A');
        if (argCount === 1) {
          stop = startIndex + 1;
          values = [explicitArg];
        } else {
          throw new ArgumentError(ArgumentParser.actionName(action), 'ignored explicit argument');
        }
      } else {
        const start = startIndex + 1;
        const argCount = this.matchArgument(action, pattern.slice(start));
        stop = start + argCount;
        values = args.slice(start, stop);
      }
      takeAction(action, values, optionString);
      return stop;
    };

    /**
     * Consume as many positionals as the pattern allows.
     */
    const consumePositionals = (startIndex) => {
      const slice = pattern.slice(startIndex);
      const counts = ArgumentParser.matchArgumentsPartial(pendingPositionals, slice);
      let cursor = startIndex;
      for (let i = 0; i < counts.length; i += 1) {
        const action = pendingPositionals[i];
        const values = args.slice(cursor, cursor + counts[i]);
        cursor += counts[i];
        takeAction(action, values, null);
      }
      pendingPositionals.splice(0, counts.length);
      return cursor;
    };

    const optionPositions = Object.keys(optionIndices).map(Number);
    const maxOptionIndex = optionPositions.length > 0 ? Math.max(...optionPositions) : -1;
    let startIndex = 0;

    while (startIndex <= maxOptionIndex) {
      const nextOptionIndex = Math.min(
        ...optionPositions.filter((position) => position >= startIndex),
      );

      if (startIndex !== nextOptionIndex) {
        const positionalsEnd = consumePositionals(startIndex);
        if (positionalsEnd > startIndex) {
          startIndex = positionalsEnd;
          continue;
        }
        startIndex = positionalsEnd;
      }

      if (startIndex !== nextOptionIndex) {
        extras.push(...args.slice(startIndex, nextOptionIndex));
        startIndex = nextOptionIndex;
      }

      startIndex = consumeOptional(nextOptionIndex);
    }

    const stopIndex = consumePositionals(startIndex);
    extras.push(...args.slice(stopIndex));

    // Required actions are reported before any leftover tokens are, which is
    // why a missing option masks an unrecognized one.
    const missing = this.actions
      .filter((action) => !seen.includes(action) && action.required)
      .map((action) => ArgumentParser.actionName(action));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  /**
   * `_get_values` -- apply `type` and collapse to a single value where the
   * action expects one.
   *
   * @param {import('./actions.mjs').Action} action
   * @param {string[]} argStrings
   * @returns {*}
   */
  getValues(action, argStrings) {
    let strings = argStrings;
    if (action.optionStrings.length === 0) {
      const dashDash = strings.indexOf('--');
