/**
 * Renders an unhandled exception the way the frozen reference build does: a
 * CPython traceback on stderr, followed by PyInstaller's own bootloader notice.
 *
 * Frames are supplied by the raiser, because a JS stack cannot describe the
 * Python call site. The `anchor` field carries the `~^^^` caret row that CPython
 * 3.11+ prints under the failing sub-expression.
 */

import { stderrWrite } from '../python/sys_io.mjs';

/** Traceback frames are indented by two spaces, source lines by four. */
const FRAME_INDENT = '  ';
const SOURCE_INDENT = '    ';

/**
 * @typedef {object} Frame
 * @property {string} file
 * @property {number} line
 * @property {string} name    function name, or `<module>` at top level
 * @property {string} [source] source text, printed re-indented
 * @property {string} [anchor] caret row aligned to the re-indented source
 */

/**
 * Builds the traceback text for an exception.
 *
 * @param {import('../python/exceptions.mjs').PyException} error
 * @param {Frame[]} outerFrames frames above the raising library, outermost first
 * @returns {string}
 */
export function formatTraceback(error, outerFrames) {
  const lines = ['Traceback (most recent call last):'];
  const frames = [...outerFrames, ...(error.frames ?? [])];

  for (const frame of frames) {
    lines.push(`${FRAME_INDENT}File "${frame.file}", line ${frame.line}, in ${frame.name}`);
    // Frozen library frames carry no source, so CPython prints only the header.
    if (frame.source !== undefined) {
      lines.push(`${SOURCE_INDENT}${frame.source}`);
      if (frame.anchor !== undefined) lines.push(frame.anchor);
    }
  }

  lines.push(error.formatExceptionOnly());
  return `${lines.join('\n')}\n`;
}

/**
 * Prints the traceback plus the bootloader's failure notice. The notice embeds
 * the running process id, exactly as the reference build does.
 *
 * @param {import('../python/exceptions.mjs').PyException} error
 * @param {Frame[]} outerFrames
 * @param {string} scriptName name PyInstaller froze the entry script under
 */
export function reportUnhandled(error, outerFrames, scriptName) {
  stderrWrite(formatTraceback(error, outerFrames));
  stderrWrite(
    `[PYI-${process.pid}:ERROR] Failed to execute script '${scriptName}' `
    + 'due to unhandled exception!\n',
  );
}

