/**
 * Node port of test2.py.
 *
 *   import argparse
 *   from bidict import bidict
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--key', type=str, required=True)
 *   parser.add_argument('--val', type=str, required=True)
 *   args = parser.parse_args()
 *
 *   # 创建双向字典并访问值
 *   b = bidict({'a': 1, 'b': 2})
 *   result = b[args.key]
 *   print(result)
 *
 * Run as: node test2.mjs --key a --val 83
 */

import { ArgumentParser, str } from './lib/argparse/parser.mjs';
import { bidict } from './lib/bidict/index.mjs';
import { print } from './lib/python/sys_io.mjs';
import { PyException, SystemExit } from './lib/python/exceptions.mjs';
import { reportUnhandled } from './lib/runtime/pyinstaller.mjs';

/**
 * The `<module>` frame of test2.py, as it appears in a traceback. Line 11 is
 * `result = b[args.key]`; the caret row marks the subscript that raised.
 */
const MODULE_FRAME = Object.freeze({
  file: 'test2.py',
  line: 11,
  name: '<module>',
  source: 'result = b[args.key]',
  anchor: `${' '.repeat(13)}~^^^^^^^^^^`,
});

/** Name PyInstaller froze the entry script under. */
const SCRIPT_NAME = 'test2';

function main() {
  const parser = new ArgumentParser();
  parser.addArgument(['--key'], { type: str, required: true });
  parser.addArgument(['--val'], { type: str, required: true });
  const args = parser.parseArgs(process.argv.slice(2));

  // 创建双向字典并访问值
  // Passed as explicit pairs so key insertion order and value types (int, not
  // string) survive exactly as they do in the Python literal.
  const b = bidict([
    ['a', 1],
    ['b', 2],
  ]);
  const result = b.getItem(args.key);
  print(result);
}

try {
  main();
} catch (error) {
  if (error instanceof SystemExit) {
    process.exit(error.code);
  }
  if (error instanceof PyException) {
    // An uncaught Python exception: traceback, then exit status 1.
    reportUnhandled(error, [MODULE_FRAME], SCRIPT_NAME);
    process.exit(1);
  }
  throw error;
}

