/**
 * `linecache.getline` emulation.
 *
 * A traceback frame stores the *filename as compiled* -- here the bare relative
 * name `test2.py`. CPython resolves it against the current working directory at
 * the moment the traceback is printed, so whether the offending source line
 * appears depends on where the program was launched from. The reference build
 * behaves exactly this way: run it beside test2.py and the line shows up, run it
 * anywhere else and the frame is header-only.
 */

import { readFileSync } from 'node:fs';

/**
 * Fetches one 1-based line, including its trailing newline, or `''` when the
 * file is unreadable or too short. Mirrors linecache's swallow-all-errors
 * contract.
 *
 * @param {string} filename
 * @param {number} lineno 1-based
 * @returns {string}
 */
export function getline(filename, lineno) {
  let contents;
  try {
    contents = readFileSync(filename, 'utf8');
  } catch {
    return '';
  }
  // Python's `str.splitlines(keepends=True)` for the newline styles that matter.
  const lines = contents.match(/[^\n]*\n|[^\n]+/g) ?? [];
  if (lineno < 1 || lineno > lines.length) return '';
  return lines[lineno - 1];
}

/**
 * `StackSummary._byte_offset_to_character_offset`: code objects record column
 * offsets in UTF-8 bytes, while the caret row is laid out in characters.
 *
 * @param {string} text
 * @param {number} byteOffset
 * @returns {number} character (code point) offset, clamped to the text length
 */
export function byteOffsetToCharacterOffset(text, byteOffset) {
  const bytes = Buffer.from(text, 'utf8');
  const prefix = bytes.subarray(0, byteOffset).toString('utf8');
  return [...prefix].length;
}

/**
 * Number of leading whitespace characters that printing strips off, used to
 * shift the caret row left along with the re-indented source line.
 *
 * @param {string} rawLine
 * @returns {number}
 */
export function strippedCharacterCount(rawLine) {
  return [...rawLine].length - [...rawLine.replace(/^\s+/, '')].length;
}

