/**
 * The `~^^^` caret row CPython 3.11+ draws beneath the sub-expression that
 * raised.
 *
 * CPython re-parses the failing source segment and, when it is a subscript,
 * marks the object being indexed with `~` and the subscript itself with `^`.
 * When the segment does not parse -- which happens whenever the file on disk no
 * longer matches what was compiled -- it falls back to an undifferentiated run
 * of `^`.
 *
 * Only the subscript shape is recognised here, because that is the only
 * expression this program can fail inside. Anything else takes the fallback,
 * which is also what CPython does for unparseable text.
 */

import { byteOffsetToCharacterOffset, strippedCharacterCount } from './linecache.mjs';

const PRIMARY_CHAR = '~';
const SECONDARY_CHAR = '^';

/**
 * Matches `<primary>[<subscript>]` where the primary is a name/attribute chain.
 * The trailing `]` must close the segment, mirroring a full-segment parse.
 */
const SUBSCRIPT_RE = /^([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\[(.*)\]$/;

/**
 * @typedef {object} Anchors
 * @property {number} leftEnd      chars covered by `~` before the subscript
 * @property {number} rightStart   char offset where the trailing `~` run resumes
 */

/**
 * `_extract_caret_anchors_from_line_segment`, restricted to subscripts.
 *
 * @param {string} segment
 * @returns {Anchors|null} null when the segment is not a recognisable subscript
 */
export function extractCaretAnchors(segment) {
  const match = SUBSCRIPT_RE.exec(segment);
  if (match === null) return null;
  const primary = match[1];
  return {
    // `~` spans the object being indexed; `^` spans `[...]` through the close.
    leftEnd: [...primary].length,
    rightStart: [...segment].length,
  };
}

/**
 * Builds the source line and caret row for a frame, given the column offsets
 * recorded in the code object.
 *
 * @param {string} rawLine    line as fetched from disk, trailing newline included
 * @param {number} colno      start column, in UTF-8 bytes
 * @param {number} endColno   end column, in UTF-8 bytes
 * @returns {{source: string, anchor: string|null}|null} null when there is no
 *   line to show at all
 */
export function renderSourceAndAnchor(rawLine, colno, endColno) {
  if (rawLine === '') return null;

  const strippedLine = rawLine.trim();
  const stripped = strippedCharacterCount(rawLine);
  const startOffset = byteOffsetToCharacterOffset(rawLine, colno);
  const endOffset = byteOffsetToCharacterOffset(rawLine, endColno);
  const segment = [...rawLine].slice(startOffset, endOffset).join('');
  const anchors = extractCaretAnchors(segment);

  const span = endOffset - startOffset;
  const strippedLength = [...strippedLine].length;
  // CPython suppresses the caret row when the marked span already covers the
  // whole visible line and there is no `~`/`^` distinction to draw.
  const show = span < strippedLength || (anchors !== null && anchors.rightStart - anchors.leftEnd > 0);
  if (!show) return { source: strippedLine, anchor: null };

  const pad = ' '.repeat(Math.max(startOffset - stripped, 0));
  let carets;
  if (anchors !== null) {
    carets = PRIMARY_CHAR.repeat(anchors.leftEnd)
      + SECONDARY_CHAR.repeat(anchors.rightStart - anchors.leftEnd)
      + PRIMARY_CHAR.repeat(Math.max(span - anchors.rightStart, 0));
  } else {
    carets = SECONDARY_CHAR.repeat(Math.max(span, 0));
  }

  return { source: strippedLine, anchor: `    ${pad}${carets}` };
}

