/**
 * Consume one optional starting at `startIndex`; returns the next index.
 *
 * A single-dash flag that takes no value can carry more flags in its tail
 * (`-hx`), so this loops, peeling one character at a time, and only then
 * applies the collected actions.
 */
const consumeOptional = (startIndex) => {
  let [action, optionString, sep, explicitArg] = optionIndices[startIndex];
  /** @type {Array<[import('./actions.mjs').Action, string[], string]>} */
  const actionTuples = [];
  let stop;

  for (;;) {
    if (action === null) {
      extras.push(args[startIndex]);
      return startIndex + 1;
    }

    if (explicitArg === null || explicitArg === undefined) {
      const start = startIndex + 1;
      const argCount = this.matchArgument(action, pattern.slice(start));
      stop = start + argCount;
      actionTuples.push([action, args.slice(start, stop), optionString]);
      break;
    }

    const argCount = this.matchArgument(action, 'A');

    // Tail-peeling applies only to a single-dash flag whose value was
    // concatenated (not written with `=`) and whose tail does not itself
    // begin with a prefix char -- `-hx` peels, `-h=x` and `-h-h` do not.
    const canPeelTail = argCount === 0
      && (sep === '' || sep === null)
      && !this.prefixChars.includes(optionString[1])
      && explicitArg !== ''
      && !this.prefixChars.includes(explicitArg[0]);

    if (canPeelTail) {
      actionTuples.push([action, [], optionString]);
      const char = optionString[0];
      optionString = char + explicitArg[0];
      const nextAction = this.optionStringActions[optionString];
      if (nextAction === undefined) {
        extras.push(char + explicitArg);
        stop = startIndex + 1;
        break;
      }
      action = nextAction;
      explicitArg = explicitArg.slice(1);
      if (explicitArg === '') {
        sep = null;
        explicitArg = null;
      } else if (explicitArg[0] === '=') {
        sep = '=';
        explicitArg = explicitArg.slice(1);
      } else {
        sep = '';
      }
    } else if (argCount === 1) {
      stop = startIndex + 1;
      actionTuples.push([action, [explicitArg], optionString]);
      break;
    } else {
      throw new ArgumentError(
        ArgumentParser.actionName(action),
        `ignored explicit argument ${pyRepr(explicitArg)}`,
      );
    }
  }

  for (const [act, values, optStr] of actionTuples) {
    takeAction(act, values, optStr);
  }
  return stop;
};

