/**
 * Recovers `sys.argv` with Python's semantics.
 *
 * CPython decodes the raw argv bytes as UTF-8 with the `surrogateescape` error
 * handler, so a byte that cannot be decoded survives as U+DC80+byte rather than
 * being lost. Node instead decodes `process.argv` with U+FFFD replacement, which
 * is irreversible -- `--key $'\xff'` would report the wrong missing key.
 *
 * The original bytes are still available on Linux via /proc/self/cmdline, so
 * they are re-read from there and decoded the way CPython would. Anywhere that
 * file is unavailable, `process.argv` is used as-is.
 */

import { readFileSync } from 'node:fs';

/** Lone-surrogate base used by the surrogateescape handler. */
const SURROGATE_BASE = 0xdc00;

/**
 * UTF-8 decode with `errors='surrogateescape'`: each undecodable byte becomes
 * one lone surrogate, and decoding resumes at the next byte.
 *
 * @param {Buffer} bytes
 * @returns {string}
 */
export function decodeSurrogateEscape(bytes) {
  let out = '';
  let index = 0;

  while (index < bytes.length) {
    const lead = bytes[index];

    if (lead < 0x80) {
      out += String.fromCharCode(lead);
      index += 1;
      continue;
    }

    // Sequence length and the smallest code point it may legally encode, so
    // that overlong forms are rejected the way a strict decoder rejects them.
    let length;
    let accumulator;
    let minimum;
    if (lead >= 0xc2 && lead <= 0xdf) {
      length = 2; accumulator = lead & 0x1f; minimum = 0x80;
    } else if (lead >= 0xe0 && lead <= 0xef) {
      length = 3; accumulator = lead & 0x0f; minimum = 0x800;
    } else if (lead >= 0xf0 && lead <= 0xf4) {
      length = 4; accumulator = lead & 0x07; minimum = 0x10000;
    } else {
      // 0x80-0xc1 and 0xf5-0xff can never start a sequence.
      out += String.fromCharCode(SURROGATE_BASE + lead);
      index += 1;
      continue;
    }

    let valid = index + length <= bytes.length;
    let codePoint = accumulator;
    if (valid) {
      for (let offset = 1; offset < length; offset += 1) {
        const continuation = bytes[index + offset];
        if ((continuation & 0xc0) !== 0x80) { valid = false; break; }
        codePoint = (codePoint << 6) | (continuation & 0x3f);
      }
    }
    // Surrogate code points are not valid UTF-8 either.
    if (valid && (codePoint < minimum || codePoint > 0x10ffff
      || (codePoint >= 0xd800 && codePoint <= 0xdfff))) {
      valid = false;
    }

    if (!valid) {
